const items = $input.all();
const output = [];

const HIGH_PRIORITY_KEYWORDS = [
  'interview', 'job offer', 'offer letter',
  'interview invitation', 'application deadline',
  'hiring', 'recruiter', 'job application',
  'job opportunity', 'job opening',
  'employment offer', 'appointment letter',
  'meeting invitation', 'project deadline',
  'urgent task', 'client request',
  'salary negotiation', 'contract agreement'
];

const MEDIUM_PRIORITY_KEYWORDS = [
  'course', 'udemy', 'coursera', 'edx',
  'tutorial', 'training', 'certification',
  'certificate', 'webinar', 'workshop',
  'seminar', 'programming', 'newsletter',
  'machine learning', 'data science',
  'python', 'javascript', 'react',
  'career development', 'skill development',
  'technical article', 'research paper'
];

const LOW_PRIORITY_KEYWORDS = [
  'sale', 'discount', 'shopping',
  'amazon', 'daraz', 'order confirmation',
  'shipping update', 'delivery update',
  'unsubscribe', 'promotion',
  'limited time', 'buy now'
];

const SECURITY_KEYWORDS = [
  'security alert',
  'suspicious activity',
  'unauthorized access',
  'new sign-in',
  'new signin',
  'password changed',
  'password reset',
  'account compromised',
  'verify your account',
  'two-step verification',
  'two factor authentication',
  '2-step verification',
  'unusual activity',
  'security notification'
];

const PROMOTION_SENDER_KEYWORDS = [
  'newsletter',
  'marketing',
  'promotions',
  'no-reply',
  'noreply'
];

for (const item of items) {
  const email = { ...item.json };

  // Normalize available email fields.
  const subject = String(email.subject || '').toLowerCase();
  const sender = String(
    email.senderEmail || email.from || ''
  ).toLowerCase();

  const content = [
    email.subject,
    email.snippet,
    email.bodyText,
    email.fullContent
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  let category = 2;
  let priorityScore = 3;
  let reason = 'General or unclassified email';
  let needsReply = false;

  // 1. Security alerts take precedence over ordinary keywords.
  const securityKeyword = SECURITY_KEYWORDS.find(
    keyword =>
      subject.includes(keyword) ||
      content.includes(keyword)
  );

  if (securityKeyword) {
    category = 0;
    priorityScore = 10;
    reason = `Security alert detected: "${securityKeyword}"`;
    needsReply = false;

  } else {
    // 2. Match meaningful high-priority job/work phrases.
    const highKeyword = HIGH_PRIORITY_KEYWORDS.find(
      keyword => content.includes(keyword)
    );

    if (highKeyword) {
      category = 0;
      priorityScore = 9;
      reason = `High priority: "${highKeyword}" detected`;
      needsReply = true;

    } else {
      // 3. Match learning and career-development content.
      const mediumKeyword = MEDIUM_PRIORITY_KEYWORDS.find(
        keyword => content.includes(keyword)
      );

      if (mediumKeyword) {
        category = 1;
        priorityScore = 6;
        reason = `Medium priority: "${mediumKeyword}" detected`;

      } else {
        // 4. Match promotional and shopping content.
        const lowKeyword = LOW_PRIORITY_KEYWORDS.find(
          keyword => content.includes(keyword)
        );

        if (lowKeyword) {
          category = 2;
          priorityScore = 3;
          reason = `Low priority: "${lowKeyword}" detected`;

        } else {
          // 5. Handle obvious promotional/newsletter senders.
          const isPromotionalSender =
            PROMOTION_SENDER_KEYWORDS.some(
              keyword => sender.includes(keyword)
            );

          if (isPromotionalSender) {
            category = 2;
            priorityScore = 2;
            reason = 'Likely automated or promotional email';
          }
        }
      }
    }
  }

  // Assign the custom Gmail label created for each category.
  let priorityLabel;

  if (category === 0) {
    priorityLabel = 'AI-High-Priority';
  } else if (category === 1) {
    priorityLabel = 'AI-Medium-Priority';
  } else {
    priorityLabel = 'AI-Low-Priority';
  }

  // Preserve the fields required by the existing workflow.
  email.category = category;
  email.priorityScore = priorityScore;
  email.priorityLabel = priorityLabel;
  email.reason = reason;
  email.needsReply = needsReply;
  email.labelIdsToApply = [priorityLabel];

  output.push({ json: email });
}

return output;

const items = $input.all();
const replies = [];

for (const item of items) {
  const rawText =
    item.json.output?.[0]?.content?.[0]?.text ||
    item.json.text ||
    item.json.response ||
    item.json.output ||
    '';

  const cleanText = String(rawText).trim();

  let parsed = {};

  try {
    // Remove Markdown code fences if the model returns them.
    const normalizedText = cleanText
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '')
      .trim();

    parsed = JSON.parse(normalizedText);
  } catch (e) {
    // Preserve a plain-text reply if the output is not JSON.
    parsed = {
      subject: '(No Subject)',
      body: cleanText,
      senderEmail: item.json.senderEmail || ''
    };
  }

  const reply = {
    subject: parsed.subject || '(No Subject)',
    body: parsed.body || cleanText,
    senderEmail: parsed.senderEmail || item.json.senderEmail || ''
  };

  replies.push({ json: reply });
}

return replies;

